real_T proc_control::proc_control_rt_atan2d_snf(real_T u0, real_T u1)
{
  real_T y;
  if (std::isnan(u0) || std::isnan(u1)) {
    y = (rtNaN);
  } else if (std::isinf(u0) && std::isinf(u1)) {
    int32_T tmp;
    if (u0 > 0.0) {
      proc_control_B.i90 = 1;
    } else {
      proc_control_B.i90 = -1;
    }

    if (u1 > 0.0) {
      tmp = 1;
    } else {
      tmp = -1;
    }

    y = std::atan2(static_cast<real_T>(proc_control_B.i90), static_cast<real_T>
                   (tmp));
  } else if (u1 == 0.0) {
    if (u0 > 0.0) {
      y = RT_PI / 2.0;
    } else if (u0 < 0.0) {
      y = -(RT_PI / 2.0);
    } else {
      y = 0.0;
    }
  } else {
    y = std::atan2(u0, u1);
  }

  return y;
}

