void proc_control::proc_control_ppval(const real_T pp_breaks[4], const real_T
  pp_coefs[36], real_T x, real_T v[3])
{
  // Start for MATLABSystem: '<S352>/Polynomial Trajectory'
  if (std::isnan(x)) {
    v[0] = (rtNaN);
    v[1] = (rtNaN);
    v[2] = (rtNaN);
  } else {
    int32_T high_i;
    proc_control_B.low_i = 0;
    proc_control_B.low_ip1 = 1;
    high_i = 4;
    while (high_i > proc_control_B.low_ip1 + 1) {
      proc_control_B.ic0 = ((proc_control_B.low_i + high_i) + 1) >> 1;
      if (x >= pp_breaks[proc_control_B.ic0 - 1]) {
        proc_control_B.low_i = proc_control_B.ic0 - 1;
        proc_control_B.low_ip1 = proc_control_B.ic0;
      } else {
        high_i = proc_control_B.ic0;
      }
    }

    proc_control_B.low_ip1 = proc_control_B.low_i * 3;
    proc_control_B.xloc = x - pp_breaks[proc_control_B.low_i];
    proc_control_B.v_o = pp_coefs[proc_control_B.low_ip1];
    proc_control_B.v_g = pp_coefs[proc_control_B.low_ip1 + 1];
    proc_control_B.v_p = pp_coefs[proc_control_B.low_ip1 + 2];
    for (high_i = 0; high_i < 3; high_i++) {
      proc_control_B.ic0 = ((high_i + 1) * 9 + proc_control_B.low_ip1) - 1;
      proc_control_B.v_o = proc_control_B.xloc * proc_control_B.v_o +
        pp_coefs[proc_control_B.ic0 + 1];
      proc_control_B.v_g = proc_control_B.xloc * proc_control_B.v_g +
        pp_coefs[proc_control_B.ic0 + 2];
      proc_control_B.v_p = proc_control_B.xloc * proc_control_B.v_p +
        pp_coefs[proc_control_B.ic0 + 3];
    }

    v[2] = proc_control_B.v_p;
    v[1] = proc_control_B.v_g;
    v[0] = proc_control_B.v_o;
  }

  // End of Start for MATLABSystem: '<S352>/Polynomial Trajectory'
}

void proc_control::proc_TrajectoryManager_stepImpl
  (TrajectoryManager_proc_contro_T *b_this, real_T reset, const real_T poses[13],
   const real_T target[7], const real_T x0[7], const real_T mesuredPose[13],
   real_T currentPose[130], boolean_T *isReached)
{
  boolean_T exitg1;
  boolean_T exitg2;
  boolean_T isempty;
  boolean_T y;

  //  Main execute a chaque iteration.
  //  Implement algorithm. Calculate y as a function of input u and
  for (proc_control_B.b_jcol_p = 0; proc_control_B.b_jcol_p < 7;
       proc_control_B.b_jcol_p++) {
    proc_control_B.mp[proc_control_B.b_jcol_p] =
      mesuredPose[proc_control_B.b_jcol_p];
  }

  if (reset == 1.0) {
    b_this->init = 0.0;
  }

  if (b_this->init == 0.0) {
    //  Conditions Initiales
    for (proc_control_B.b_jcol_p = 0; proc_control_B.b_jcol_p < 7;
         proc_control_B.b_jcol_p++) {
      proc_control_B.a_d[proc_control_B.b_jcol_p] = x0[proc_control_B.b_jcol_p];
    }

    proc_control_B.a_d[7] = 0.0;
    proc_control_B.a_d[8] = 0.0;
    proc_control_B.a_d[9] = 0.0;
    proc_control_B.a_d[10] = 0.0;
    proc_control_B.a_d[11] = 0.0;
    proc_control_B.a_d[12] = 0.0;
    proc_control_B.b_jcol_p = 0;
    for (proc_control_B.b_jcol = 0; proc_control_B.b_jcol < 13;
         proc_control_B.b_jcol++) {
      for (proc_control_B.b_itilerow = 0; proc_control_B.b_itilerow < 10;
           proc_control_B.b_itilerow++) {
        b_this->poseBuffer[proc_control_B.b_itilerow + proc_control_B.b_jcol_p] =
          proc_control_B.a_d[proc_control_B.b_jcol];
      }

      proc_control_B.b_jcol_p += 6001;
    }

    // InitCond;
    b_this->bufferCount = 1.0;
    b_this->init = 1.0;
  }

  // Start for MATLABSystem: '<S336>/MATLAB System1'
  // this.BufferReset(reset,mp);
  //  Fonction qui traites les nouveau poses.
  //  Insertion des nouveaux points.
  // if new == this.generationNumber %new>
  if (b_this->bufferCount + 1.0 < 6001.0) {
    for (proc_control_B.b_jcol_p = 0; proc_control_B.b_jcol_p < 13;
         proc_control_B.b_jcol_p++) {
      b_this->poseBuffer[(static_cast<int32_T>(b_this->bufferCount + 1.0) + 6001
                          * proc_control_B.b_jcol_p) - 1] =
        poses[proc_control_B.b_jcol_p];
    }

    // this.poseBuffer(this.bufferCount:count + this.bufferCount,:) = pose(1:count+1,:) 
    b_this->bufferCount++;
    b_this->generationNumber++;
  } else {
    std::printf("%s\n", "Problem");
    std::fflush(stdout);
  }

  //  Fonction qui retourne la pose actuelle
  //  Vérification des prédictions.
  proc_control_B.b_index = 2;
  isempty = false;
  proc_control_B.b_itilerow = 0;
  exitg1 = false;
  while ((!exitg1) && (proc_control_B.b_itilerow < 9)) {
    proc_control_B.b_index = proc_control_B.b_itilerow + 2;
    for (proc_control_B.b_jcol_p = 0; proc_control_B.b_jcol_p < 13;
         proc_control_B.b_jcol_p++) {
      proc_control_B.x_o[proc_control_B.b_jcol_p] = (b_this->poseBuffer[(6001 *
        proc_control_B.b_jcol_p + proc_control_B.b_itilerow) + 1] ==
        b_this->emptyArray[proc_control_B.b_jcol_p]);
    }

    y = true;
    proc_control_B.b_jcol = 0;
    exitg2 = false;
    while ((!exitg2) && (proc_control_B.b_jcol < 13)) {
      if (!proc_control_B.x_o[proc_control_B.b_jcol]) {
        y = false;
        exitg2 = true;
      } else {
        proc_control_B.b_jcol++;
      }
    }

    if (y) {
      isempty = true;
      exitg1 = true;
    } else {
      proc_control_B.b_itilerow++;
    }
  }

  std::memset(&currentPose[0], 0, 130U * sizeof(real_T));
  proc_control_B.b_jcol_p = 0;
  proc_control_B.b_jcol = 0;
  for (proc_control_B.b_itilerow = 0; proc_control_B.b_itilerow < 13;
       proc_control_B.b_itilerow++) {
    // Start for MATLABSystem: '<S336>/MATLAB System1'
    for (proc_control_B.b_index_k = 0; proc_control_B.b_index_k <
         proc_control_B.b_index; proc_control_B.b_index_k++) {
      currentPose[proc_control_B.b_index_k + proc_control_B.b_jcol_p] =
        b_this->poseBuffer[proc_control_B.b_index_k + proc_control_B.b_jcol];
    }

    proc_control_B.b_jcol_p += 10;
    proc_control_B.b_jcol += 6001;
  }

  if (isempty) {
    proc_control_B.b_itilerow = 11 - proc_control_B.b_index;
    for (proc_control_B.b_jcol = 0; proc_control_B.b_jcol <
         proc_control_B.b_itilerow; proc_control_B.b_jcol++) {
      // Start for MATLABSystem: '<S336>/MATLAB System1'
      proc_control_B.b_index_k = proc_control_B.b_index + proc_control_B.b_jcol;
      for (proc_control_B.b_jcol_p = 0; proc_control_B.b_jcol_p < 13;
           proc_control_B.b_jcol_p++) {
        proc_control_B.a_d[proc_control_B.b_jcol_p] = currentPose[(10 *
          proc_control_B.b_jcol_p + proc_control_B.b_index) - 2];
      }

      for (proc_control_B.b_jcol_p = 0; proc_control_B.b_jcol_p < 13;
           proc_control_B.b_jcol_p++) {
        currentPose[(proc_control_B.b_index_k + 10 * proc_control_B.b_jcol_p) -
          1] = proc_control_B.a_d[proc_control_B.b_jcol_p];
      }
    }
  }

  //  Ne pas supprimer le point si c'est le dernier.
  proc_control_B.b_jcol_p = 0;
  for (proc_control_B.b_jcol = 0; proc_control_B.b_jcol < 13;
       proc_control_B.b_jcol++) {
    // Start for MATLABSystem: '<S336>/MATLAB System1'
    proc_control_B.x_o[proc_control_B.b_jcol] = !(b_this->
      poseBuffer[proc_control_B.b_jcol_p + 10] == b_this->
      emptyArray[proc_control_B.b_jcol]);
    proc_control_B.b_jcol_p += 6001;
  }

  y = true;
  proc_control_B.b_jcol = 0;
  exitg1 = false;
  while ((!exitg1) && (proc_control_B.b_jcol < 13)) {
    if (!proc_control_B.x_o[proc_control_B.b_jcol]) {
      y = false;
      exitg1 = true;
    } else {
      proc_control_B.b_jcol++;
    }
  }

  if (y) {
    proc_control_B.b_jcol_p = 0;
    for (proc_control_B.b_jcol = 0; proc_control_B.b_jcol < 13;
         proc_control_B.b_jcol++) {
      // Start for MATLABSystem: '<S336>/MATLAB System1'
      std::memcpy(&proc_control_B.b_this[proc_control_B.b_jcol_p],
                  &b_this->poseBuffer[proc_control_B.b_jcol_p + 1], 6000U *
                  sizeof(real_T));
      proc_control_B.b_this[proc_control_B.b_jcol_p + 6000] = b_this->
        emptyArray[proc_control_B.b_jcol];
      proc_control_B.b_jcol_p += 6001;
    }

    // Start for MATLABSystem: '<S336>/MATLAB System1'
    std::memcpy(&b_this->poseBuffer[0], &proc_control_B.b_this[0], 78013U *
                sizeof(real_T));
    b_this->bufferCount--;
  }

  //  Fonction qui verifie le target reached
  //  vérifier si la trajectoire est fini
  for (proc_control_B.b_jcol_p = 0; proc_control_B.b_jcol_p < 7;
       proc_control_B.b_jcol_p++) {
    // Start for MATLABSystem: '<S336>/MATLAB System1'
    proc_control_B.y_j[proc_control_B.b_jcol_p] = std::abs
      (poses[proc_control_B.b_jcol_p] - target[proc_control_B.b_jcol_p]);
  }

  // Start for MATLABSystem: '<S336>/MATLAB System1'
  b_this->done = true;
  proc_control_B.b_jcol = 0;
  exitg1 = false;
  while ((!exitg1) && (proc_control_B.b_jcol < 7)) {
    if (!(proc_control_B.y_j[proc_control_B.b_jcol] < 0.001)) {
      b_this->done = false;
      exitg1 = true;
    } else {
      proc_control_B.b_jcol++;
    }
  }

  *isReached = false;

  // Start for MATLABSystem: '<S336>/MATLAB System1'
  //  vérifier le traget reached si la trajectoire est terminé
  if (b_this->done) {
    //  check flip
    // =================================================================
    //  Fonction qui assure la continuité entre 2 quaternions
    //  Regarder la discontinuité entre le qk et qk-1
    proc_control_B.mp[3] = mesuredPose[3];
    proc_control_B.mp[4] = mesuredPose[4];
    proc_control_B.mp[5] = mesuredPose[5];
    proc_control_B.mp[6] = mesuredPose[6];
    if (((target[3] * mesuredPose[3] + target[4] * mesuredPose[4]) + target[5] *
         mesuredPose[5]) + target[6] * mesuredPose[6] < 0.0) {
      proc_control_B.mp[3] = -mesuredPose[3];
      proc_control_B.mp[4] = -mesuredPose[4];
      proc_control_B.mp[5] = -mesuredPose[5];
      proc_control_B.mp[6] = -mesuredPose[6];
    }

    //  calculer l'erreur angulaire.
    // =================================================================
    //  Fonction qui calcule l'angle entre 2 quaternion
    proc_control_B.qRel[0] = ((target[3] * proc_control_B.mp[3] - -target[4] *
      proc_control_B.mp[4]) - -target[5] * proc_control_B.mp[5]) - -target[6] *
      proc_control_B.mp[6];
    proc_control_B.qRel[1] = (target[3] * proc_control_B.mp[4] + -target[4] *
      proc_control_B.mp[3]) + (-target[5] * proc_control_B.mp[6] - -target[6] *
      proc_control_B.mp[5]);
    proc_control_B.qRel[2] = (target[3] * proc_control_B.mp[5] + -target[5] *
      proc_control_B.mp[3]) + (-target[6] * proc_control_B.mp[4] - -target[4] *
      proc_control_B.mp[6]);
    proc_control_B.qRel[3] = (target[3] * proc_control_B.mp[6] +
      proc_control_B.mp[3] * -target[6]) + (-target[4] * proc_control_B.mp[5] -
      -target[5] * proc_control_B.mp[4]);

    //  vérifier si le sub est dans la zone de convergence (sphérique / conique) 
    proc_control_B.target[0] = target[0] - proc_control_B.mp[0];
    proc_control_B.target[1] = target[1] - proc_control_B.mp[1];
    proc_control_B.target[2] = target[2] - proc_control_B.mp[2];
    if ((proc_control_norm_pr3(proc_control_B.target) <
         b_this->linearConvergence) && (2.0 * proc_control_rt_atan2d_snf
         (proc_control_norm_pr3(&proc_control_B.qRel[1]), proc_control_B.qRel[0])
         < b_this->quaternionConvergence)) {
      b_this->targetReachedCount++;
      *isReached = (b_this->targetReachedCount * 0.1 >= b_this->TargetThreshold);
    } else {
      b_this->targetReachedCount = 0.0;
    }
  }
}

